class PWA{constructor(){this.deferredPrompt=null,this.isInstalled=!1,this.autoHideTimer=null}getSettings(){return{enabled:"true"===localStorage.getItem("admin_installPromptEnabled"),message:localStorage.getItem("admin_installMessage")||"Install OFF-THE-RECORD for easy access and offline reading",buttonText:localStorage.getItem("admin_installButton")||"Install",delay:1e3*parseInt(localStorage.getItem("admin_installDelay")||"1"),autoHide:1e3*parseInt(localStorage.getItem("admin_installAutoHide")||"0")}}trackInstall(){const t=parseInt(localStorage.getItem("admin_installCount")||"0");localStorage.setItem("admin_installCount",t+1)}init(){"serviceWorker"in navigator&&this.registerServiceWorker(),this.checkIfInstalled(),window.addEventListener("beforeinstallprompt",t=>{t.preventDefault(),this.deferredPrompt=t,this.isInstalled||this.showInstallPrompt()}),window.addEventListener("appinstalled",()=>{this.isInstalled=!0,this.trackInstall(),this.hideInstallPrompt()})}async registerServiceWorker(){try{const t=await navigator.serviceWorker.register("./sw.js");t.addEventListener("updatefound",()=>{const e=t.installing;e.addEventListener("statechange",()=>{"installed"===e.state&&navigator.serviceWorker.controller&&this.showUpdateNotification()})})}catch(t){console.error("Service Worker registration failed:",t)}}checkIfInstalled(){window.matchMedia("(display-mode: standalone)").matches?this.isInstalled=!0:!0!==window.navigator.standalone?document.referrer.includes("android-app://")&&(this.isInstalled=!0):this.isInstalled=!0}showInstallPrompt(){const t=this.getSettings();if(!t.enabled)return;if("true"===localStorage.getItem("installPromptDismissed"))return;const e=document.createElement("div");e.className="install-prompt",e.id="installPrompt",e.innerHTML=`\n            <div class="install-prompt-text">\n                ${t.message}\n            </div>\n            <button class="install-btn" id="installBtn">${t.buttonText}</button>\n            <button class="dismiss-install" id="dismissInstall" aria-label="Dismiss">✕</button>\n        `,document.body.appendChild(e),setTimeout(()=>{e.classList.add("show"),t.autoHide>0&&(this.autoHideTimer=setTimeout(()=>{this.hideInstallPrompt()},t.autoHide))},t.delay),document.getElementById("installBtn").addEventListener("click",()=>{this.handleInstallClick()}),document.getElementById("dismissInstall").addEventListener("click",()=>{localStorage.setItem("installPromptDismissed","true"),this.hideInstallPrompt()})}async handleInstallClick(){if(!this.deferredPrompt)return;this.deferredPrompt.prompt();const{outcome:t}=await this.deferredPrompt.userChoice;"dismissed"===t&&localStorage.setItem("installPromptDismissed","true"),this.deferredPrompt=null,this.hideInstallPrompt()}hideInstallPrompt(){this.autoHideTimer&&(clearTimeout(this.autoHideTimer),this.autoHideTimer=null);const t=document.getElementById("installPrompt");t&&(t.classList.remove("show"),setTimeout(()=>{t.remove()},300))}showUpdateNotification(){const t=document.createElement("div");t.className="update-notification",t.innerHTML='\n            <div>A new version is available</div>\n            <button onclick="window.location.reload()">Reload</button>\n        ',document.body.appendChild(t),setTimeout(()=>{t.remove()},1e4)}}export const pwa=new PWA;